    63	static uint32_t probe_get_le32(const uint8_t *value)
    64	{
    65	  return (uint32_t)value[0] |
    66	         ((uint32_t)value[1] << 8) |
    67	         ((uint32_t)value[2] << 16) |
    68	         ((uint32_t)value[3] << 24);
    69	}
    70	
    71	static void probe_put_le32(uint8_t *value, uint32_t number)
    72	{
    73	  value[0] = (uint8_t)number;
    74	  value[1] = (uint8_t)(number >> 8);
    75	  value[2] = (uint8_t)(number >> 16);
    76	  value[3] = (uint8_t)(number >> 24);
    77	}
