    79	static bt_status_t probe_notify(gatts_handle_t srv_handle,
    80	                                uint8_t *value, uint16_t length)
    81	{
    82	  if (!g_peer_connected || !g_notify_enabled)
    83	    {
    84	      printf("openvela_ble_probe: TX notification not subscribed\n");
    85	      return BT_STATUS_NOT_READY;
    86	    }
    87	
    88	  return bt_gatts_notify(srv_handle, &g_peer_addr, PROBE_TX_HANDLE,
    89	                         value, length);
    90	}
