   122	static uint16_t probe_tx_cccd_written(gatts_handle_t srv_handle,
   123	                                      bt_address_t *addr,
   124	                                      uint16_t attr_handle,
   125	                                      const uint8_t *value,
   126	                                      uint16_t length,
