   137	      return 0;
   138	    }
   139	
   140	  cccd = (uint16_t)value[0] | ((uint16_t)value[1] << 8);
   141	  memcpy(&g_peer_addr, addr, sizeof(g_peer_addr));
   142	  g_notify_enabled = (cccd & GATT_CCC_NOTIFY) != 0;
   143	
   144	  printf("openvela_ble_probe: TX notify=%d\n", g_notify_enabled);
   145	  return length;
   146	}
