    92	static uint32_t probe_elapsed_ms(const struct timespec *started_at)
    93	{
    94	  struct timespec ended_at;
    95	  int64_t seconds;
    96	  int64_t nanoseconds;
    97	  uint64_t milliseconds;
    98	
    99	  if (clock_gettime(CLOCK_MONOTONIC, &ended_at) < 0)
   100	    {
   101	      return 0;
   102	    }
   103	
   104	  seconds = ended_at.tv_sec - started_at->tv_sec;
   105	  nanoseconds = ended_at.tv_nsec - started_at->tv_nsec;
   106	  if (nanoseconds < 0)
   107	    {
   108	      seconds--;
   109	      nanoseconds += 1000000000;
   110	    }
   111	
   112	  if (seconds < 0)
   113	    {
   114	      return 0;
   115	    }
   116	
   117	  milliseconds = (uint64_t)seconds * 1000 +
   118	                 (uint64_t)nanoseconds / 1000000;
   119	  return milliseconds > UINT32_MAX ? UINT32_MAX : (uint32_t)milliseconds;
   120	}
