+#define SF32LB52_BT_NORMALIZE_RESET_STATUS 0

 #ifndef BT_HCI_OP_READ_SUPPORTED_COMMANDS
 #  define BT_HCI_OP_READ_SUPPORTED_COMMANDS BT_OP(BT_OGF_INFO, 0x0002)
@@ -282,7 +285,9 @@ static int sf32lb52_bt_forward_packet(struct sf32lb52_bt_priv_s *priv,
   switch (data[0])
     {
       case H4_EVT:
-        sf32lb52_bt_normalize_event(data, len);
+        #if SF32LB52_BT_NORMALIZE_RESET_STATUS
+          sf32lb52_bt_normalize_event(data, len);
+        #endif
         type = BT_EVT;
         break;

@@ -570,12 +575,32 @@ static int sf32lb52_bt_send(struct bt_driver_s *drv,
   if (type == BT_CMD && len >= sizeof(struct bt_hci_cmd_hdr_s))
     {
       opcode = sf32lb52_bt_get_le16(data);
