+            "sf32lb52 bth4 hci tx: opcode=0x%04x len=%lu\n",
+            opcode, (unsigned long)len);
+    #endif
+
+  #if SF32LB52_BT_COMPAT_BR_INIT
+    if (opcode == BT_HCI_OP_WRITE_LOCAL_NAME)
+      {
+        syslog(LOG_INFO,
+               "sf32lb52 bth4 compat: synth BR init opcode=0x%04x\n",
+               opcode);
+        ret = sf32lb52_bt_synth_status_complete(priv, opcode);
+        return ret < 0 ? ret : len;
+      }
+    #endif
+
+  #if SF32LB52_BT_EMULATE_HCI
+    if (sf32lb52_bt_emulate_cmd(priv, opcode, &ret))
+    {
+      return ret < 0 ? ret : len;
+    }
+    #endif
+
