#include "bt_gatts.h"
#include "bt_le_advertiser.h"

#define PROBE_SERVICE_UUID 0xfff0
#define PROBE_RX_UUID      0xfff1
#define PROBE_TX_UUID      0xfff2

enum probe_attr_handle_e
{
  PROBE_SERVICE_HANDLE = 1,
  PROBE_RX_HANDLE,
  PROBE_TX_HANDLE,
  PROBE_TX_CCCD_HANDLE,
};

static sem_t g_ble_on_sem;
static volatile bool g_ble_on;

static bt_instance_t *g_instance;
static bt_advertiser_t *g_advertiser;
static gatts_handle_t g_service_handle;

static advertiser_data_t *g_adv_data;
static advertiser_data_t *g_scan_rsp_data;
static uint8_t *g_adv_payload;
static uint8_t *g_scan_rsp_payload;
static uint16_t g_adv_payload_len;
static uint16_t g_scan_rsp_payload_len;

static bt_address_t g_peer_addr;
static bool g_peer_connected;
static bool g_notify_enabled;
static bool g_restart_advertising_pending;
static bool g_restart_advertising_thread_running;
static pthread_mutex_t g_restart_advertising_lock = PTHREAD_MUTEX_INITIALIZER;

static uint8_t g_pong[] = { 'P', 'O', 'N', 'G' };
static uint8_t g_error[] = { 'E', 'R', 'R' };

struct probe_throughput_state_s
{
  bool active;
  bool timing;
  bool have_expected_seq;
  uint32_t test_id;
  uint32_t frames;
  uint32_t payload_bytes;
  uint32_t expected_seq;
  uint32_t missing_frames;
  struct timespec started_at;
};

static struct probe_throughput_state_s g_throughput;

static int start_advertising(void);

static void *restart_advertising_after_disconnect(void *arg)
{
  bool restart;

  (void)arg;
  sleep(1);

  pthread_mutex_lock(&g_restart_advertising_lock);
  restart = g_restart_advertising_pending && !g_peer_connected &&
            g_advertiser == NULL;
  if (restart)
    {
      g_restart_advertising_pending = false;
    }

  g_restart_advertising_thread_running = false;
  pthread_mutex_unlock(&g_restart_advertising_lock);

  if (restart)
    {
      printf("openvela_ble_probe: restart advertising after disconnect\n");
      if (start_advertising() < 0)
        {
          printf("openvela_ble_probe: restart advertising failed\n");
        }
    }

  return NULL;
}

static void schedule_advertising_restart(void)
{
  pthread_attr_t attr;
  pthread_t thread;
  int ret;

  pthread_mutex_lock(&g_restart_advertising_lock);
  if (!g_restart_advertising_pending ||
      g_restart_advertising_thread_running)
    {
      pthread_mutex_unlock(&g_restart_advertising_lock);
      return;
    }

  g_restart_advertising_thread_running = true;
  pthread_mutex_unlock(&g_restart_advertising_lock);

  ret = pthread_attr_init(&attr);
  if (ret == 0)
    {
      ret = pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_DETACHED);
      if (ret == 0)
        {
          ret = pthread_create(&thread, &attr,
                               restart_advertising_after_disconnect, NULL);
        }

      pthread_attr_destroy(&attr);
    }

  if (ret != 0)
    {
      pthread_mutex_lock(&g_restart_advertising_lock);
      g_restart_advertising_thread_running = false;
      pthread_mutex_unlock(&g_restart_advertising_lock);
      printf("openvela_ble_probe: advertising restart schedule failed=%d\n",
             ret);
    }
  else
    {
      printf("openvela_ble_probe: advertising restart scheduled\n");
    }
}

