    54	  bool have_expected_seq;
    55	  uint32_t test_id;
    56	  uint32_t frames;
    57	  uint32_t payload_bytes;
    58	  uint32_t expected_seq;
    59	  uint32_t missing_frames;
    60	  struct timespec started_at;
    61	};
    62	
    63	static struct probe_throughput_state_s g_throughput;
    64	
    65	static uint32_t probe_get_le32(const uint8_t *value)
    66	{
    67	  return (uint32_t)value[0] |
    68	         ((uint32_t)value[1] << 8) |
    69	         ((uint32_t)value[2] << 16) |
    70	         ((uint32_t)value[3] << 24);
    71	}
    72	
    73	static void probe_put_le32(uint8_t *value, uint32_t number)
    74	{
    75	  value[0] = (uint8_t)number;
    76	  value[1] = (uint8_t)(number >> 8);
    77	  value[2] = (uint8_t)(number >> 16);
    78	  value[3] = (uint8_t)(number >> 24);
    79	}
    80	
    81	static bt_status_t probe_notify(gatts_handle_t srv_handle,
    82	                                uint8_t *value, uint16_t length)
    83	{
    84	  if (!g_peer_connected || !g_notify_enabled)
    85	    {
    86	      printf("openvela_ble_probe: TX notification not subscribed\n");
    87	      return BT_STATUS_NOT_READY;
    88	    }
    89	
    90	  return bt_gatts_notify(srv_handle, &g_peer_addr, PROBE_TX_HANDLE,
    91	                         value, length);
    92	}
    93	
    94	static uint32_t probe_elapsed_ms(const struct timespec *started_at)
    95	{
    96	  struct timespec ended_at;
    97	  int64_t seconds;
    98	  int64_t nanoseconds;
    99	  uint64_t milliseconds;
   100	
   101	  if (clock_gettime(CLOCK_MONOTONIC, &ended_at) < 0)
   102	    {
   103	      return 0;
   104	    }
   105	
   106	  seconds = ended_at.tv_sec - started_at->tv_sec;
   107	  nanoseconds = ended_at.tv_nsec - started_at->tv_nsec;
   108	  if (nanoseconds < 0)
   109	    {
   110	      seconds--;
   111	      nanoseconds += 1000000000;
   112	    }
   113	
   114	  if (seconds < 0)
   115	    {
   116	      return 0;
   117	    }
   118	
   119	  milliseconds = (uint64_t)seconds * 1000 +
   120	                 (uint64_t)nanoseconds / 1000000;
   121	  return milliseconds > UINT32_MAX ? UINT32_MAX : (uint32_t)milliseconds;
   122	}
   123	
   124	static uint16_t probe_tx_cccd_written(gatts_handle_t srv_handle,
   125	                                      bt_address_t *addr,
   126	                                      uint16_t attr_handle,
   127	                                      const uint8_t *value,
   128	                                      uint16_t length,
   129	                                      uint16_t offset)
   130	{
   131	  uint16_t cccd;
   132	
   133	  (void)srv_handle;
   134	  (void)attr_handle;
   135	
   136	  if (offset != 0 || length < 2)
   137	    {
   138	      printf("openvela_ble_probe: invalid CCCD write\n");
   139	      return 0;
   140	    }
   141	
   142	  cccd = (uint16_t)value[0] | ((uint16_t)value[1] << 8);
   143	  memcpy(&g_peer_addr, addr, sizeof(g_peer_addr));
   144	  g_notify_enabled = (cccd & GATT_CCC_NOTIFY) != 0;
   145	
   146	  printf("openvela_ble_probe: TX notify=%d\n", g_notify_enabled);
   147	  return length;
   148	}
   149	
   150	static uint16_t probe_rx_written(gatts_handle_t srv_handle,
   151	                                 bt_address_t *addr,
   152	                                 uint16_t attr_handle,
   153	                                 const uint8_t *value,
   154	                                 uint16_t length,
   155	                                 uint16_t offset)
   156	{
   157	  uint8_t response[21];
   158	  uint8_t *reply;
   159	  uint16_t reply_len;
   160	  uint32_t elapsed_ms;
   161	  uint32_t id_or_seq;
   162	  uint32_t seq;
   163	  bt_status_t status;
   164	
   165	  (void)attr_handle;
   166	
   167	  if (offset != 0)
   168	    {
   169	      printf("openvela_ble_probe: long write is not supported\n");
   170	      return 0;
   171	    }
   172	
   173	  memcpy(&g_peer_addr, addr, sizeof(g_peer_addr));
   174	
   175	  if (length == 4 && memcmp(value, "PING", 4) == 0)
   176	    {
   177	      reply = g_pong;
   178	      reply_len = sizeof(g_pong);
   179	      printf("openvela_ble_probe: RX PING\n");
   180	    }
   181	  else if (length >= 1 && value[0] == 0x01)
   182	    {
   183	      if (length < 5)
   184	        {
   185	          printf("openvela_ble_probe: short binary PING length=%u\n",
   186	                 length);
   187	          return length;
   188	        }
   189	
   190	      id_or_seq = probe_get_le32(&value[1]);
   191	      response[0] = 0x81;
   192	      probe_put_le32(&response[1], id_or_seq);
   193	      printf("openvela_ble_probe: RX binary PING seq=%lu\n",
   194	             (unsigned long)id_or_seq);
   195	      status = probe_notify(srv_handle, response, 5);
   196	      printf("openvela_ble_probe: TX binary PONG status=%d\n", status);
   197	      return length;
   198	    }
   199	  else if (length >= 1 && value[0] == 0x10)
   200	    {
   201	      if (length < 5)
   202	        {
   203	          printf("openvela_ble_probe: short START length=%u\n", length);
   204	          return length;
   205	        }
   206	
   207	      id_or_seq = probe_get_le32(&value[1]);
   208	      memset(&g_throughput, 0, sizeof(g_throughput));
   209	      g_throughput.active = true;
   210	      g_throughput.test_id = id_or_seq;
   211	
   212	      response[0] = 0x90;
   213	      probe_put_le32(&response[1], id_or_seq);
   214	      printf("openvela_ble_probe: throughput START test_id=%lu\n",
   215	             (unsigned long)id_or_seq);
   216	      status = probe_notify(srv_handle, response, 5);
   217	      printf("openvela_ble_probe: throughput START_ACK status=%d\n", status);
   218	      return length;
   219	    }
   220	  else if (length >= 1 && value[0] == 0x11)
   221	    {
   222	      if (length < 5)
   223	        {
   224	          printf("openvela_ble_probe: short DATA length=%u\n", length);
   225	          return length;
   226	        }
   227	
   228	      if (!g_throughput.active)
   229	        {
   230	          printf("openvela_ble_probe: DATA without active test\n");
   231	          return length;
   232	        }
   233	
   234	      seq = probe_get_le32(&value[1]);
   235	      if (!g_throughput.timing)
   236	        {
   237	          if (clock_gettime(CLOCK_MONOTONIC,
   238	                            &g_throughput.started_at) == 0)
   239	            {
   240	              g_throughput.timing = true;
   241	            }
   242	          else
   243	            {
   244	              printf("openvela_ble_probe: monotonic clock failed\n");
   245	            }
   246	        }
   247	
   248	      g_throughput.frames++;
   249	      g_throughput.payload_bytes += length - 5;
   250	
   251	      if (!g_throughput.have_expected_seq)
   252	        {
   253	          g_throughput.expected_seq = seq + 1;
   254	          g_throughput.have_expected_seq = true;
   255	        }
   256	      else if (seq == g_throughput.expected_seq)
   257	        {
   258	          g_throughput.expected_seq++;
   259	        }
   260	      else if (seq > g_throughput.expected_seq)
   261	        {
   262	          g_throughput.missing_frames += seq - g_throughput.expected_seq;
   263	          g_throughput.expected_seq = seq + 1;
   264	        }
   265	      else
   266	        {
   267	          g_throughput.missing_frames++;
   268	        }
   269	
   270	      return length;
   271	    }
   272	  else if (length >= 1 && value[0] == 0x12)
   273	    {
   274	      if (length < 5)
   275	        {
   276	          printf("openvela_ble_probe: short END length=%u\n", length);
   277	          return length;
   278	        }
   279	
   280	      id_or_seq = probe_get_le32(&value[1]);
   281	      if (!g_throughput.active || id_or_seq != g_throughput.test_id)
   282	        {
   283	          printf("openvela_ble_probe: unmatched END test_id=%lu\n",
   284	                 (unsigned long)id_or_seq);
   285	          return length;
   286	        }
   287	
   288	      elapsed_ms = g_throughput.timing ?
   289	                   probe_elapsed_ms(&g_throughput.started_at) : 0;
   290	      response[0] = 0x91;
   291	      probe_put_le32(&response[1], g_throughput.test_id);
   292	      probe_put_le32(&response[5], g_throughput.frames);
   293	      probe_put_le32(&response[9], g_throughput.payload_bytes);
   294	      probe_put_le32(&response[13], elapsed_ms);
   295	      probe_put_le32(&response[17], g_throughput.missing_frames);
   296	
   297	      printf("openvela_ble_probe: throughput END test_id=%lu frames=%lu "
   298	             "payload=%lu elapsed_ms=%lu missing=%lu\n",
   299	             (unsigned long)g_throughput.test_id,
   300	             (unsigned long)g_throughput.frames,
   301	             (unsigned long)g_throughput.payload_bytes,
   302	             (unsigned long)elapsed_ms,
   303	             (unsigned long)g_throughput.missing_frames);
   304	      status = probe_notify(srv_handle, response, sizeof(response));
   305	      printf("openvela_ble_probe: throughput REPORT status=%d\n", status);
   306	      memset(&g_throughput, 0, sizeof(g_throughput));
   307	      return length;
   308	    }
   309	  else
   310	    {
   311	      reply = g_error;
   312	      reply_len = sizeof(g_error);
   313	      printf("openvela_ble_probe: RX unknown command\n");
   314	    }
   315	
   316	  status = probe_notify(srv_handle, reply, reply_len);
   317	  printf("openvela_ble_probe: TX notify status=%d\n", status);
   318	  return length;
   319	}
