   407	static int init_gatt_service(void)
   408	{
   409	  bt_status_t status;
   410	
   411	  status = bt_gatts_register_service(g_instance, &g_service_handle,
   412	                                     (gatts_callbacks_t *)&g_gatts_callbacks);
   413	  if (status != BT_STATUS_SUCCESS || g_service_handle == NULL)
   414	    {
   415	      printf("openvela_ble_probe: GATT register failed:%d\n", status);
   416	      return -1;
   417	    }
   418	
   419	  status = bt_gatts_add_attr_table(g_service_handle, &g_service_db);
   420	  if (status != BT_STATUS_SUCCESS)
   421	    {
   422	      printf("openvela_ble_probe: GATT table add failed:%d\n", status);
   423	      return -1;
   424	    }
   425	
   426	  printf("openvela_ble_probe: GATT service FFF0, RX FFF1, TX FFF2\n");
   427	  return 0;
   428	}
