    45	/**
    46	 * @brief callback for GATT server recveived read request.
    47	 *
    48	 * This callback is triggered when peer GATT client initiate read request to characteristic with property
    49	 * contains the read flag bit.
    50	 *
    51	 * @param srv_handle - gatts handle(void*). Each GATT service has its own handle.
    52	 * @param addr - remote device address. Address of the peer device that initiated the read request.
    53	 * @param attr_handle - attribute handle. The handle identified by each service, not the Attribute handle in spec.
    54	 * @param req_handle - request handle. Identifies the order in which the read request was made.
    55	 * @return uint16_t.
    56	 *
    57	 * **Example:**
    58	 * @code
    59	uint16_t rx_char_on_read(void* srv_handle, bt_address_t* addr, uint16_t attr_handle, uint32_t req_handle)
    60	{
    61	    bt_status_t ret = bt_gatts_response(srv_handle, addr, req_handle, read_char_value, sizeof(read_char_value));
    62	    PRINT("gatts service RX char response. status: %d", ret);
    63	    return 0;
    64	}
    65	 * @endcode
    66	 */
    67	typedef uint16_t (*attribute_read_cb_t)(gatts_handle_t srv_handle, bt_address_t* addr, uint16_t attr_handle, uint32_t req_handle);
