   668	static void add_service(gatt_element_t* element, bool is_over_br)
   669	{
   670	    struct bt_gatt_attr* attr_svc;
   671	    union uuid u;
   672	    size_t size;
   673	
   674	    if (!bt_uuid_create(&u.uuid, (uint8_t*)&element->uuid.val, element->uuid.type)) {
   675	        BT_LOGE("%s, uuid convert fail", __func__);
   676	        return;
   677	    }
   678	
   679	    size = u.uuid.type == BT_UUID_TYPE_16 ? sizeof(u.u16) : sizeof(u.u128);
   680	
   681	    switch (element->type) {
   682	    case GATT_PRIMARY_SERVICE:
   683	        attr_svc = gatt_db_add(&(struct bt_gatt_attr)BT_GATT_PRIMARY_SERVICE(&u.uuid), size);
   684	        break;
   685	    case GATT_SECONDARY_SERVICE:
   686	        attr_svc = gatt_db_add(&(struct bt_gatt_attr)BT_GATT_SECONDARY_SERVICE(&u.uuid), size);
   687	        break;
   688	    default:
   689	        attr_svc = NULL;
   690	        break;
   691	    }
   692	
   693	    if (!attr_svc) {
   694	        BT_LOGE("%s, attr_svc is null", __func__);
   695	        return;
   696	    }
   697	}
