   729	static uint16_t covert_gatt_permission(uint16_t elem_perm)
   730	{
   731	    int chr_perm = 0;
   732	
   733	    if (elem_perm & GATT_PERM_READ) {
   734	        chr_perm |= BT_GATT_PERM_READ;
   735	        if (elem_perm & GATT_PERM_AUTHEN_REQUIRED) {
   736	            chr_perm |= BT_GATT_PERM_READ_AUTHEN;
   737	        }
   738	        if (elem_perm & GATT_PERM_ENCRYPT_REQUIRED) {
   739	            chr_perm |= BT_GATT_PERM_READ_ENCRYPT;
   740	        }
   741	        if (elem_perm & GATT_PERM_MITM_REQUIRED) {
   742	            chr_perm |= BT_GATT_PERM_READ_LESC;
   743	        }
   744	    }
   745	
   746	    if (elem_perm & GATT_PERM_WRITE) {
   747	        chr_perm |= BT_GATT_PERM_WRITE;
   748	        if (elem_perm & GATT_PERM_AUTHEN_REQUIRED) {
   749	            chr_perm |= BT_GATT_PERM_WRITE_AUTHEN;
   750	        }
   751	        if (elem_perm & GATT_PERM_ENCRYPT_REQUIRED) {
   752	            chr_perm |= BT_GATT_PERM_WRITE_ENCRYPT;
   753	        }
   754	        if (elem_perm & GATT_PERM_MITM_REQUIRED) {
   755	            chr_perm |= BT_GATT_PERM_WRITE_LESC;
   756	        }
   757	    }
   758	
   759	    return chr_perm;
   760	}
