static inline void sc_work_submit(struct bt_dev *hdev, k_timeout_t timeout)
{
#if defined(CONFIG_BT_GATT_SERVICE_CHANGED)
	k_work_reschedule(&hdev->gatt_ctx->gatt_sc.work, timeout);
