static void on_gatts_connected(gatts_handle_t srv_handle, bt_address_t *addr)
{
  (void)srv_handle;

  memcpy(&g_peer_addr, addr, sizeof(g_peer_addr));
  g_peer_connected = true;
  g_notify_enabled = false;
