}

static void on_gatts_disconnected(gatts_handle_t srv_handle,
                                  bt_address_t *addr)
{
  (void)srv_handle;
  (void)addr;

  g_notify_enabled = false;
  memset(&g_throughput, 0, sizeof(g_throughput));
