   478	        for (tnode = bt_list_head(tlist); tnode != NULL; tnode = bt_list_next(tlist, tnode)) {
   479	            service_table_t* table = (service_table_t*)bt_list_node(tnode);
   480	            gatt_element_t* element = table->elements;
   481	
   482	            BT_LOGI("\tAttribute Table[%d]: Handle:0x%04x~0x%04x, Num:%d", t_id++, table->start_handle, table->end_handle, table->element_size);
   483	            for (int i = 0; i < table->element_size; i++, element++) {
   484	                bt_uuid_to_string(&element->uuid, uuid_str, BT_UUID_STR_LENGTH);
   485	                BT_LOGI("\t\t>[0x%04x][Type:%d][Prop:%04x][UUID:%s]", element->handle, element->type, element->properties,
