   530	static bt_status_t if_gatts_unregister_service(void* srv_handle)
   531	{
   532	    gatts_service_t* service = srv_handle;
   533	
   534	    CHECK_ENABLED();
   535	    CHECK_SERVICE_VALID(g_gatts_manager.services, service);
   536	
   537	    bt_list_node_t* node;
   538	    bt_list_t* list = service->tables;
   539	    for (node = bt_list_head(list); node != NULL; node = bt_list_next(list, node)) {
   540	        service_table_t* svc_table = (service_table_t*)bt_list_node(node);
   541	        bt_sal_gatt_server_remove_elements(svc_table->elements, svc_table->element_size);
   542	    }
   543	
   544	    void** user_phandle = service->user_phandle;
   545	    pthread_mutex_lock(&g_gatts_manager.device_lock);
   546	    bt_list_remove(g_gatts_manager.services, service);
   547	    pthread_mutex_unlock(&g_gatts_manager.device_lock);
   548	    *user_phandle = NULL;
   549	
   550	    return BT_STATUS_SUCCESS;
   900	    gatts_send_message(msg);
