   382	static bt_status_t if_gatts_startup(profile_on_startup_t cb)
   383	{
   384	    bt_status_t status;
   385	    gatts_manager_t* manager = &g_gatts_manager;
   386	
   387	    pthread_mutex_lock(&manager->device_lock);
   388	    if (manager->started) {
   389	        pthread_mutex_unlock(&manager->device_lock);
   390	        cb(PROFILE_GATTS, true);
   391	        return BT_STATUS_SUCCESS;
   392	    }
   393	
   394	    manager->services = bt_list_new((bt_list_free_cb_t)gatts_service_delete);
   395	    if (!manager->services) {
   396	        status = BT_STATUS_NOMEM;
   397	        goto fail;
   398	    }
   399	
   400	    manager->pend_ops = bt_list_new((bt_list_free_cb_t)gatts_pendops_delete);
   401	    if (!manager->pend_ops) {
   402	        status = BT_STATUS_NOMEM;
   403	        goto fail;
   404	    }
   405	
   406	    status = bt_sal_gatt_server_enable();
   407	    if (status != BT_STATUS_SUCCESS)
   408	        goto fail;
   409	
   410	    manager->started = true;
   411	    pthread_mutex_unlock(&manager->device_lock);
   412	    cb(PROFILE_GATTS, true);
   413	
   414	    return BT_STATUS_SUCCESS;
   415	
   416	fail:
   417	    bt_list_free(manager->services);
   418	    manager->services = NULL;
   419	    bt_list_free(manager->pend_ops);
   420	    manager->pend_ops = NULL;
   421	    pthread_mutex_unlock(&manager->device_lock);
   422	    cb(PROFILE_GATTS, false);
   423	
   424	    return status;
   425	}
