   367	static bt_status_t if_gatts_init(void)
   368	{
   369	    pthread_mutexattr_t attr;
   370	
   371	    memset(&g_gatts_manager, 0, sizeof(g_gatts_manager));
   372	    g_gatts_manager.started = false;
   373	
   374	    pthread_mutexattr_init(&attr);
   375	    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
   376	    if (pthread_mutex_init(&g_gatts_manager.device_lock, &attr) < 0)
   377	        return BT_STATUS_FAIL;
   378	
   379	    return BT_STATUS_SUCCESS;
   380	}
