  1869	int bt_gatt_service_register_mc(uint8_t dev_id, struct bt_gatt_service *svc)
  1870	{
  1871		int err;
  1872	
  1873		__ASSERT(svc, "invalid parameters\n");
  1874		__ASSERT(svc->attrs, "invalid parameters\n");
  1875		__ASSERT(svc->attr_count, "invalid parameters\n");
  1876	
  1877		svc->hdev = bt_dev_get(dev_id);
  1878		if (!svc->hdev) {
  1879			return -ENODEV;
  1880		}
  1881	
  1882		if (IS_ENABLED(CONFIG_BT_SETTINGS) &&
  1883		    atomic_test_bit(svc->hdev->gatt_ctx->gatt_flags, GATT_INITIALIZED) &&
  1884		    !atomic_test_bit(svc->hdev->gatt_ctx->gatt_sc.flags, SC_LOAD)) {
  1885			LOG_ERR("Can't register service after init and before settings are loaded.");
  1886			return -EINVAL;
  1887		}
  1888	
  1889		/* Init GATT core services */
  1890		bt_gatt_service_init(svc->hdev);
  1891	
  1892		/* Do no allow to register mandatory services twice */
  1893		if (!bt_uuid_cmp(svc->attrs[0].uuid, BT_UUID_GAP) ||
  1894		    !bt_uuid_cmp(svc->attrs[0].uuid, BT_UUID_GATT)) {
  1895			return -EALREADY;
  1896		}
  1897	
  1898		k_sched_lock();
  1899	
  1900		err = gatt_register(svc);
  1901		if (err < 0) {
  1902			k_sched_unlock();
  1903			return err;
  1904		}
  1905	
  1906		/* Don't submit any work until the stack is initialized */
  1907		if (!atomic_test_bit(svc->hdev->gatt_ctx->gatt_flags, GATT_INITIALIZED)) {
  1908			k_sched_unlock();
  1909			return 0;
  1910		}
  1911	
  1912		sc_indicate(svc->hdev, svc->attrs[0].handle,
  1913			    svc->attrs[svc->attr_count - 1].handle);
  1914	
  1915		db_changed(svc->hdev);
  1916	
  1917		k_sched_unlock();
  1918	
  1919		return 0;
  1920	}

