  1852	static int gatt_unregister(struct bt_gatt_service *svc)
  1853	{
  1854		if (!sys_slist_find_and_remove(&svc->hdev->gatt_ctx->db, &svc->node)) {
  1855			return -ENOENT;
  1856		}
