   155	static bt_status_t zblue_le_ext_convert_param(ble_adv_params_t* params, struct bt_le_adv_param* param)
   156	{
   157	    static bt_addr_le_t addr;
   158	
   159	    switch (params->adv_type) {
   160	    case BT_LE_ADV_IND:
   161	    case BT_LE_EXT_ADV_IND:
   162	        param->options |= BT_LE_ADV_OPT_CONN;
   163	        param->options |= BT_LE_ADV_OPT_EXT_ADV;
   164	        param->options |= BT_LE_ADV_OPT_NO_2M;
   165	        break;
   166	    case BT_LE_ADV_SCAN_IND:
   167	    case BT_LE_EXT_ADV_SCAN_IND:
   168	        param->options |= BT_LE_ADV_OPT_SCANNABLE;
   169	        param->options |= BT_LE_ADV_OPT_EXT_ADV;
   170	        param->options |= BT_LE_ADV_OPT_NO_2M;
   171	        break;
   172	    case BT_LE_ADV_DIRECT_IND:
   173	    case BT_LE_EXT_ADV_DIRECT_IND:
   174	        param->options |= BT_LE_ADV_OPT_CONN;
   175	        param->options |= BT_LE_ADV_OPT_EXT_ADV;
   176	        param->options |= BT_LE_ADV_OPT_NO_2M;
   177	        param->options |= BT_LE_ADV_OPT_DIR_MODE_LOW_DUTY;
   178	        break;
   179	    case BT_LE_SCAN_RSP:
   180	    case BT_LE_EXT_SCAN_RSP:
   240	        param->options |= BT_LE_ADV_OPT_NONE;
   241	    }
   242	
   243	    param->interval_min = params->interval;
   244	    param->interval_max = params->interval;
   245	
   246	    if (params->adv_type == BT_LE_ADV_DIRECT_IND
   247	        || params->adv_type == BT_LE_EXT_ADV_DIRECT_IND
   248	        || params->adv_type == BT_LE_LEGACY_ADV_DIRECT_IND) {
   249	        addr.type = params->peer_addr_type;
   250	        memcpy(&addr.a, &params->peer_addr, sizeof(bt_address_t));
   251	        param->peer = &addr;
   252	    }
   253	
   254	    return BT_STATUS_SUCCESS;
   255	}
