  2598	static void hci_cmd_complete(struct bt_dev *hdev, struct net_buf *buf)
  2599	{
  2600		struct bt_hci_evt_cmd_complete *evt;
  2601		uint8_t status, ncmd;
  2602		uint16_t opcode;
  2603	
  2604		evt = net_buf_pull_mem(buf, sizeof(*evt));
  2605		ncmd = evt->ncmd;
  2606		opcode = sys_le16_to_cpu(evt->opcode);
  2607	
  2608		LOG_DBG("opcode 0x%04x %s", opcode, bt_hci_opcode_to_str(opcode));
  2609	
  2610		/* All command return parameters have a 1-byte status in the
  2611		 * beginning, so we can safely make this generalization.
  2612		 */
  2613		status = buf->data[0];
  2614	
  2615		/* HOST_NUM_COMPLETED_PACKETS should not generate a response under normal operation.
  2616		 * The generation of this command ignores `ncmd_sem`, so should not be given here.
  2617		 */
  2618		if (opcode == BT_HCI_OP_HOST_NUM_COMPLETED_PACKETS) {
  2619			LOG_WRN("Unexpected HOST_NUM_COMPLETED_PACKETS, status 0x%02x %s",
  2620				status, bt_hci_err_to_str(status));
  2621			return;
  2622		}
  2623	
  2624		hci_cmd_done(hdev, opcode, status, buf);
  2625	
  2626		/* Allow next command to be sent */
  2627		if (ncmd) {
  2628			k_sem_give(&hdev->ncmd_sem);
  2629			bt_tx_irq_raise(hdev);
  2630		}
  2631	}
