  2536	static void hci_cmd_done(struct bt_dev *hdev, uint16_t opcode,
  2537				 uint8_t status, struct net_buf *evt_buf)
  2538	{
  2539		/* Original command buffer. */
  2540		struct net_buf *buf = NULL;
  2541	
  2542		LOG_DBG("opcode 0x%04x %s, status 0x%02x %s buf %p", opcode,
  2543			bt_hci_opcode_to_str(opcode),
  2544			status, bt_hci_err_to_str(status), evt_buf);
  2545	
  2546		/* Unsolicited cmd complete. This does not complete a command.
  2547		 * The controller can send these for effect of the `ncmd` field.
  2548		 */
  2549		if (opcode == 0) {
  2550			goto exit;
  2551		}
  2552	
  2553		/* Take the original command buffer reference. */
  2554		buf = (struct net_buf *)atomic_ptr_clear((atomic_ptr_t *)&hdev->sent_cmd);
  2555	
  2556		if (!buf) {
  2557			LOG_ERR("No command sent for cmd complete 0x%04x", opcode);
  2558			goto exit;
  2559		}
  2560	
  2561		if (cmd(buf)->opcode != opcode) {
  2562			LOG_ERR("OpCode 0x%04x %s completed instead of expected 0x%04x %s", opcode,
  2563				bt_hci_opcode_to_str(opcode), cmd(buf)->opcode, bt_hci_opcode_to_str(cmd(buf)->opcode));
  2564			buf = atomic_ptr_set((atomic_ptr_t *)&hdev->sent_cmd, buf);
  2565			__ASSERT_NO_MSG(!buf);
  2566			goto exit;
  2567		}
  2568	
  2569		/* Response data is to be delivered in the original command
  2570		 * buffer.
  2571		 */
  2572		if (evt_buf != buf) {
  2573			net_buf_reset(buf);
  2574			bt_buf_set_type(buf, BT_BUF_EVT);
  2575			net_buf_reserve(buf, BT_BUF_RESERVE);
  2576			net_buf_add_mem(buf, evt_buf->data, evt_buf->len);
  2577		}
  2578	
  2579		if (cmd(buf)->state && !status) {
  2580			struct bt_hci_cmd_state_set *update = cmd(buf)->state;
  2581	
  2582			atomic_set_bit_to(update->target, update->bit, update->val);
  2583		}
  2584	
  2585		/* If the command was synchronous wake up bt_hci_cmd_send_sync() */
  2586		if (cmd(buf)->sync) {
  2587			LOG_DBG("sync cmd released");
  2588			cmd(buf)->status = status;
  2589			k_sem_give(cmd(buf)->sync);
  2590		}
  2591	
  2592	exit:
  2593		if (buf) {
  2594			net_buf_unref(buf);
  2595		}
  2596	}
