  2604		evt = net_buf_pull_mem(buf, sizeof(*evt));
  2605		ncmd = evt->ncmd;
  2606		opcode = sys_le16_to_cpu(evt->opcode);
  2607	
  2608		LOG_DBG("opcode 0x%04x %s", opcode, bt_hci_opcode_to_str(opcode));
  2609	
  2610		/* All command return parameters have a 1-byte status in the
  2611		 * beginning, so we can safely make this generalization.
  2612		 */
  2613		status = buf->data[0];
