  4233	static void rx_queue_put(struct bt_dev *hdev, struct net_buf *buf)
  4234	{
  4235		net_buf_slist_put(&hdev->rx_queue, buf);
  4236	
  4237	#if defined(CONFIG_BT_RECV_WORKQ_SYS)
  4238		const int err = k_work_submit(&hdev->rx_work);
  4239	#elif defined(CONFIG_BT_RECV_WORKQ_BT)
  4240		const int err = k_work_submit_to_queue(&bt_workq, &hdev->rx_work);
  4241	#endif /* CONFIG_BT_RECV_WORKQ_SYS */
  4242		if (err < 0) {
  4243			LOG_ERR("Could not submit rx_work: %d", err);
  4244		}
  4245	}
  4246	
  4247	static int bt_recv_unsafe(struct bt_dev *hdev, struct net_buf *buf)
  4248	{
  4249		bt_monitor_send(bt_monitor_opcode(buf), buf->data, buf->len);
  4250	
  4251		LOG_DBG("buf %p len %u", buf, buf->len);
  4252	
  4253		switch (bt_buf_get_type(buf)) {
  4254	#if defined(CONFIG_BT_CONN)
  4255		case BT_BUF_ACL_IN:
  4256			rx_queue_put(hdev, buf);
  4257			return 0;
  4258	#endif /* BT_CONN */
  4259		case BT_BUF_EVT:
  4260		{
  4261			struct bt_hci_evt_hdr *hdr = (void *)buf->data;
  4262			uint8_t evt_flags = bt_hci_evt_get_flags(hdr->evt);
  4263	
  4264			if (evt_flags & BT_HCI_EVT_FLAG_RECV_PRIO) {
  4265				hci_event_prio(hdev, buf);
  4266			}
  4267	
  4268			if (evt_flags & BT_HCI_EVT_FLAG_RECV) {
  4269				rx_queue_put(hdev, buf);
  4270			}
  4271	
  4272			return 0;
  4273		}
  4274	#if defined(CONFIG_BT_ISO)
  4275		case BT_BUF_ISO_IN:
  4276			rx_queue_put(hdev, buf);
  4277			return 0;
  4278	#endif /* CONFIG_BT_ISO */
  4279		default:
  4280			LOG_ERR("Invalid buf type %u", bt_buf_get_type(buf));
  4281			net_buf_unref(buf);
  4282			return -EINVAL;
  4283		}
  4284	}
  4285	
  4420		default:
  4421			LOG_ERR("Unknown buf type %u", bt_buf_get_type(buf));
  4422			net_buf_unref(buf);
  4423			break;
  4424		}
  4425	
  4426		/* Schedule the work handler to be executed again if there are
  4427		 * additional items in the queue. This allows for other users of the
  4428		 * work queue to get a chance at running, which wouldn't be possible if
  4429		 * we used a while() loop with a k_yield() statement.
  4430		 */
  4431		if (!sys_slist_is_empty(&hdev->rx_queue)) {
  4432	
  4433	#if defined(CONFIG_BT_RECV_WORKQ_SYS)
  4434			err = k_work_submit(&hdev->rx_work);
  4435	#elif defined(CONFIG_BT_RECV_WORKQ_BT)
  4436			err = k_work_submit_to_queue(&bt_workq, &hdev->rx_work);
  4437	#endif
  4438			if (err < 0) {
  4439				LOG_ERR("Could not submit rx_work: %d", err);
  4440			}
  4441		}
  4442	}
