   547	static int sf32lb52_bt_recv_cb(uint8_t *data, uint16_t len)
   548	{
   549	  struct sf32lb52_bt_priv_s *priv = &g_sf32lb52_bt_priv;
   550	  ssize_t packet_len;
   551	  int ret;
   552	
   553	  if (data == NULL || len == 0)
   554	    {
   555	      return -EINVAL;
   556	    }
   557	
   558	  if (priv->drop_rx_until_tx)
   559	    {
   560	      return OK;
   561	    }
   562	
   563	  if (priv->rxlen + len > sizeof(priv->rxbuf))
   564	    {
   565	      syslog(LOG_ERR,
   566	             "sf32lb52 bth4 rx overflow: pending=%lu incoming=%u\n",
   567	             (unsigned long)priv->rxlen,
   568	             len);
   569	      priv->rxlen = 0;
   570	    }
   571	
   572	  memcpy(&priv->rxbuf[priv->rxlen], data, len);
   573	  priv->rxlen += len;
   574	
   575	#if SF32LB52_BT_TRACE
   576	  if (priv->rxbuf[0] != H4_ACL || SF32LB52_BT_TRACE_ACL)
   577	    {
   578	      syslog(LOG_INFO,
   579	             "sf32lb52 bth4 recv: len=%u pending=%lu first=%02x\n",
   580	             len, (unsigned long)priv->rxlen, priv->rxbuf[0]);
   581	    }
   582	#endif
   583	
   584	  ret = OK;
   585	
   586	  while (priv->rxlen > 0)
   587	    {
   588	      packet_len = sf32lb52_bt_h4_packet_len(priv->rxbuf, priv->rxlen);
   589	      if (packet_len == 0)
   590	        {
   591	          break;
   592	        }
   593	
   594	      if (packet_len < 0)
   595	        {
   596	          syslog(LOG_WARNING,
   597	                 "sf32lb52 bth4 drop invalid h4 type=%02x pending=%lu\n",
   598	                 priv->rxbuf[0],
   599	                 (unsigned long)priv->rxlen);
   600	          memmove(priv->rxbuf, &priv->rxbuf[1], priv->rxlen - 1);
