630	static int sf32lb52_bt_send(struct bt_driver_s *drv,
631	                            enum bt_buf_type_e type,
632	                            void *data, size_t len)
633	{
634	  struct sf32lb52_bt_priv_s *priv = &g_sf32lb52_bt_priv;
635	  uint8_t *hdr = (uint8_t *)data - drv->head_reserve;
636	  uint16_t opcode;
637	  int ret;
638	
639	  switch (type)
640	    {
641	      case BT_CMD:
642	        *hdr = H4_CMD;
643	        break;
644	      case BT_ACL_OUT:
645	        *hdr = H4_ACL;
646	        break;
647	      case BT_ISO_OUT:
648	        *hdr = H4_ISO;
649	        break;
650	      default:
651	        return -EINVAL;
652	    }
653	
654	  if (type == BT_CMD && len >= sizeof(struct bt_hci_cmd_hdr_s))
655	    {
656	      opcode = sf32lb52_bt_get_le16(data);
657	
658	  #if SF32LB52_BT_TRACE
659	    syslog(LOG_INFO,
660	            "sf32lb52 bth4 hci tx: opcode=0x%04x len=%lu\n",
661	            opcode, (unsigned long)len);
662	    #endif
663	
664	  #if SF32LB52_BT_COMPAT_BR_INIT
665	    if (opcode == BT_HCI_OP_WRITE_LOCAL_NAME)
666	      {
667	        syslog(LOG_INFO,
668	               "sf32lb52 bth4 compat: synth BR init opcode=0x%04x\n",
669	               opcode);
670	        ret = sf32lb52_bt_synth_status_complete(priv, opcode);
671	        return ret < 0 ? ret : len;
672	      }
673	    #endif
674	
675	  #if SF32LB52_BT_EMULATE_HCI
676	    if (sf32lb52_bt_emulate_cmd(priv, opcode, &ret))
677	    {
678	      return ret < 0 ? ret : len;
679	    }
680	    #endif
